function formatPrice(amount: number, currency = "EUR", decimals = 2): string {
  return `${amount.toFixed(decimals)} ${currency}`;
}

function applyDiscount(price: number, percent: number): number {
  if (percent < 0 || percent > 100) {
    throw new RangeError(`Invalid discount: ${percent}%`);
  }
  return price - (price * percent) / 100;
}

console.log(formatPrice(19.999));
console.log(formatPrice(applyDiscount(80, 25), "USD"));
console.log(formatPrice(5, "JPY", 0));

interface Book {
  readonly isbn: string;
  title: string;
  authors: string[];
  pages: number;
  publishedYear?: number;
}

function summarize(book: Book): string {
  const year = book.publishedYear ?? "unknown year";
  return `${book.title} by ${book.authors.join(" & ")} (${year}, ${book.pages} pages)`;
}

