type Payment =
  | { method: "card"; last4: string; amount: number }
  | { method: "paypal"; email: string; amount: number }
  | { method: "cash"; amount: number };

function receipt(payment: Payment): string {
  switch (payment.method) {
    case "card":
      return `Card ending ${payment.last4}: ${payment.amount}`;
    case "paypal":
      return `PayPal (${payment.email}): ${payment.amount}`;
    case "cash":
      return `Cash: ${payment.amount}`;
    default: {
      const unreachable: never = payment;
      return unreachable;
    }
  }
}

const payments: Payment[] = [
  { method: "card", last4: "4242", amount: 30 },
  { method: "paypal", email: "ada@example.com", amount: 12.5 },
  { method: "cash", amount: 5 },
];

for (const payment of payments) {
  console.log(receipt(payment));
}

function groupBy<T, K extends string>(
  items: readonly T[],
  keyOf: (item: T) => K,
): Partial<Record<K, T[]>> {
  const groups: Partial<Record<K, T[]>> = {};
  for (const item of items) {
    const key = keyOf(item);
    (groups[key] ??= []).push(item);
  }
  return groups;
}

