class Temperature {
  static fromFahrenheit(value: number): Temperature {
    return new Temperature(((value - 32) * 5) / 9);
  }

  #celsius: number;

  constructor(celsius: number) {
    if (celsius < -273.15) {
      throw new RangeError("Below absolute zero");
    }
    this.#celsius = celsius;
  }

  get celsius(): number {
    return this.#celsius;
  }

  set celsius(value: number) {
    this.#celsius = Math.max(value, -273.15);
  }

  get fahrenheit(): number {
    return (this.#celsius * 9) / 5 + 32;
  }

  toString(): string {
    return `${this.#celsius.toFixed(1)} °C`;
  }
}

const boiling = new Temperature(100);
const body = Temperature.fromFahrenheit(98.6);
body.celsius = 36.6;

console.log(String(boiling), boiling.fahrenheit);
console.log(String(body));

interface User {
  id: number;
  email: string;
  displayName: string;
  passwordHash: string;
  createdAt: string;
}

type CreateUserDto = Omit<User, "id" | "createdAt">;
type UpdateUserDto = Partial<Pick<User, "email" | "displayName">>;
type PublicUser = Omit<User, "passwordHash">;

function createUser(input: CreateUserDto, nextId: number): User {
  return { ...input, id: nextId, createdAt: "2026-11-15" };
}

function toPublic(user: User): PublicUser {
  const { passwordHash: _hidden, ...safe } = user;
  return safe;
}

function updateUser(user: User, changes: UpdateUserDto): User {
  return { ...user, ...changes };
}

const user = createUser(
  { email: "ada@example.com", displayName: "Ada", passwordHash: "$argon2$..." },
  1,
);

console.log(toPublic(updateUser(user, { displayName: "Ada L." })));

type Listener<Args extends unknown[]> = (...args: Args) => void;

class TypedEmitter<Events extends Record<string, unknown[]>> {
  private listeners: { [K in keyof Events]?: Listener<Events[K]>[] } = {};

  on<K extends keyof Events>(event: K, listener: Listener<Events[K]>): void {
    (this.listeners[event] ??= []).push(listener);
  }

  emit<K extends keyof Events>(event: K, ...args: Events[K]): void {
    for (const listener of this.listeners[event] ?? []) {
      listener(...args);
    }
  }
}

type AppEvents = {
  login: [userId: number, at: string];
  logout: [];
};

const bus = new TypedEmitter<AppEvents>();

bus.on("login", (userId, at) => console.log(`user ${userId} logged in at ${at}`));
bus.on("logout", () => console.log("logged out"));

bus.emit("login", 7, "09:30");
