type Result<T> = { ok: true; value: T } | { ok: false; error: string };

async function fetchJson<T>(
  url: string,
  isValid: (value: unknown) => value is T,
): Promise<Result<T>> {
  try {
    const response = await fetch(url);
    if (!response.ok) {
      return { ok: false, error: `HTTP ${response.status}` };
    }
    const body: unknown = await response.json();
    return isValid(body) ? { ok: true, value: body } : { ok: false, error: "Unexpected shape" };
  } catch (error) {
    return { ok: false, error: error instanceof Error ? error.message : String(error) };
  }
}

interface Repo {
  name: string;
  stars: number;
}

function isRepo(value: unknown): value is Repo {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return typeof candidate.name === "string" && typeof candidate.stars === "number";
}

const result = await fetchJson("https://api.example.com/repos/typescript", isRepo);

if (result.ok) {
  console.log(`${result.value.name} has ${result.value.stars} stars`);
} else {
  console.log(`Request failed: ${result.error}`);
}

function splitName(full: string): [first: string, last: string] {
  const [first = "", ...rest] = full.trim().split(/\s+/);
  return [first, rest.join(" ")];
}

function minMax(values: readonly number[]): [min: number, max: number] | undefined {
  if (values.length === 0) return undefined;
  return [Math.min(...values), Math.max(...values)];
}

const [first, last] = splitName("Grace Brewster Hopper");
console.log(first, "|", last);

const range = minMax([7, 2, 9]);
if (range) {
  const [min, max] = range;
  console.log(`from ${min} to ${max}`);
}
console.log(minMax([]));

